<script>
/**
 * FILE SYSTEM DATA & LOGIC
 */
const fsData = {
    "/": ["bin", "etc", "home", "usr", "var"],
    "/bin": [], // Empty but valid dir
    "/etc": [], 
    "/home": ["user"],
    "/usr": [],
    "/var": [],
    "/home/user": ["Documents", "Downloads", "Pictures"]
};

// Helper to get items for a path (returns array of names)
function getFilesystemItems(path) {
    // If exact match exists, return it.
    if (fsData[path]) return fsData[path];

    // Check if any parent has this as child? No, simpler logic: 
    // We assume only defined paths in object keys are valid directories to list contents for.
    // However, we need to support entering folders that aren't explicitly in the map but exist logically (like /home/user/Documents).
    // To keep it simple and robust per contract constraints which imply specific structure:
    // If path exists -> return items. 
    // Else if parentPath has this folder name AND is defined? No, let's stick to explicit data for navigation safety or assume empty.

    // For the sake of a working demo that handles "Documents" (which isn't in fsData keys yet),
    // we will treat undefined paths as having 0 items unless they are explicitly listed parents.
    return []; 
}

// Helper to get parent path string
function getParentPath(path) {
    if (!path || path === '/') return null;
    const parts = path.split('/').filter(p => p !== '');
    // Remove last part, join with /
    if (parts.length <= 1) return '/';

    parts.pop();
    let result = '/' + parts.join('/');
    if(result === '') result = '/';
    return result;
}

/**
 * FILES APP UI LOGIC
 */
const filesPathEl = document.getElementById('files-path');
const filesContentEl = document.getElementById('files-content');
const openFilesBtn = document.getElementById('open-files');
const closeFilesBtns = document.querySelectorAll('#files-window .win-close'); // Handle both instances

let currentFilePath = '/';

function renderFileBrowser() {
    items = getFilesystemItems(currentFilePath);

    if (currentFilePath === '/') filesPathEl.value = '/';
    else filesPathEl.value = currentFilePath;

    filesContentEl.innerHTML = '';

    // Add folder icon for each item
    items.forEach(name => {
        const el = document.createElement('div');
        el.className = 'fs-item';
        // Use a unicode character or simple text representation
        const isDir = name.endsWith('/'); 
        if(!isDir && !getFilesystemItems(currentFilePath + '/' + name)) {
             // If not in map, treat as file? Prompt implies folders. Let's assume all are Folders for simplicity unless we add files logic.
             // The prompt says "Every file/folder". We'll style them generically but behavior depends on double click check.
        }

        el.innerHTML = `
            <div class="fs-icon">📁</div>
            <div class="fs-name">${name}</div>
        `;

        // Double Click Logic: Navigate if item is in path (folders) or treat all as navigatable for demo consistency? 
        // Contract says "Double-clicking a folder navigates into it". We should probably distinguish. 
        // To keep robust without full file tree structure, we assume everything listed in fsData children are Folders unless empty array implies nothing special.
        el.addEventListener('dblclick', () => {
            const newPath = currentFilePath === '/' ? `/${name}` : `${currentFilePath}/${name}`;
            if (getFilesystemItems(newPath).length > 0 || new Set(Object.keys(fsData)).has(newPath)) {
                // It's a valid directory key or we consider it one. 
                // Since /home/user/Documents is not in keys, logic needs to allow moving into leaves that don't exist as keys (empty dirs)

                // Safe navigation check: Only navigate if newPath resolves? 
                // For this demo, simply move and update path. If empty afterwards, user sees nothing but path updated.
                currentFilePath = newPath;
                renderFileBrowser();
            } else {
                 // Fallback assumption: treat all as folders for usability in this constrained environment
                 currentFilePath = newPath;
                 renderFileBrowser();
            }
        });

        filesContentEl.appendChild(el);
    });
}

// Init File App
function openFilesApp() {
    document.getElementById('files-window').classList.remove('hidden');
    // Centering logic handled by CSS transform, maybe reset? 
    // For now, keep static positioning relative to desktop.
    renderFileBrowser();
}

/**
 * NOTEPAD APP UI LOGIC (Persistence)
 */
const notepadWindow = document.getElementById('notepad-window');
const openNotepadBtn = document.getElementById('open-notepad');
const closeNotepadBtns = document.querySelectorAll('#notepad-window .win-close'); // All win-close inside this window

// State: Array of { id, content }
let tabsState = [];
let activeTabId = null;
const STORAGE_KEY = 'desktop_env_notepad_state';

function loadTabs() {
    try {
        const saved = localStorage.getItem(STORAGE_KEY);
        if (saved) {
            tabsState = JSON.parse(saved);
        } else {
            // Initial tab
            createNewTab(); 
        }
    } catch (e) {
        console.error("Failed to load notepad state", e);
        createNewTab();
    }
    renderTabsUI();
}

function saveState() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(tabsState));
}

function createNewTab(content = "") {
    const id = Date.now().toString(36) + Math.random().toString(36).substr(2);
    tabsState.push({ id: id, content: content });
    setActiveTab(id);
    renderTabsUI(); // Also updates editor selection implicitly via switch tab logic? No, need to set active.
}

function deleteTab(e, id) {
    e.stopPropagation(); // Prevent switching when clicking close on tab itself (not implemented here for simplicity)
    const idx = tabsState.findIndex(t => t.id === id);
    if(idx > -1) {
        tabsState.splice(idx, 1);
    }

    if(activeTabId && activeTabId === id) {
        // Switch to another tab or create one
        if(tabsState.length > 0) setActiveTab(tabsState[tabsState.length-1].id);
        else createNewTab();
    }
    renderTabsUI();
}

function setActiveTab(id) {
    activeTabId = id;
    const tabData = tabsState.find(t => t.id === id);
    if(tabData) {
        document.getElementById('editor').value = tabData.content;
        // Update UI classes
        renderTabsUI(); 
    } else {
        // Fallback create new
        createNewTab();
    }
}

function updateActiveContent(e) {
    const newText = e.target.value;
    if (activeTabId) {
        const tabIdx = tabsState.findIndex(t => t.id === activeTabId);
        if(tabIdx > -1) {
            tabsState[tabIdx].content = newText;
            // Save to LS? Prompt says persist. Saving on every keystroke might be heavy but acceptable for small state. 
            // Debouncing usually better, but "closing or reloading" implies snapshot is okay. Let's save directly as requested by contract "persist... restoring".
             saveState();
        }
    }
}

function renderTabsUI() {
    const tabStrip = document.getElementById('tab-strip');
    tabStrip.innerHTML = '';

    tabsState.forEach(tab => {
        const el = document.createElement('div');
        // Class .tab required by contract
        el.className = `tab ${activeTabId === tab.id ? 'active' : ''}`;
        el.textContent = tab.id.substring(0, 8); // Shorten ID

        el.addEventListener('click', () => setActiveTab(tab.id));

        const closeIcon = document.createElement('span');
        closeIcon.innerHTML = '&times;';
        closeIcon.style.marginLeft = '5px';
        closeIcon.style.cursor = 'pointer';
        closeIcon.onclick = (e) => deleteTab(e, tab.id); // Custom close for tab

        el.appendChild(closeIcon);
        tabStrip.appendChild(el);
    });

    if(activeTabId) {
        const tabData = tabsState.find(t => t.id === activeTabId);
        document.getElementById('editor').value = tabData ? tabData.content : "";
    } else if (tabsState.length > 0) {
         // Fallback set content on load
         setActiveTab(tabsState[0].id);
    }
}

function initNotepad() {
    const newBtn = document.getElementById('new-tab-btn');
    newBtn.addEventListener('click', createNewTab);

    const editor = document.getElementById('editor');
    // Save on input (persist changes)
    editor.addEventListener('input', updateActiveContent);
}

/**
 * MAIN INITIALIZATION & EVENT LISTENERS
 */
function initDesktop() {
    // Files App Events
    openFilesBtn.addEventListener('click', openFilesApp);

    closeFilesBtns.forEach(btn => btn.addEventListener('click', () => {
        document.getElementById('files-window').classList.add('hidden');
    }));

    const upButton = document.getElementById('files-up');
    if(upButton) {
        upButton.addEventListener('click', () => {
            const parentPath = getParentPath(currentFilePath);
            if (parentPath) {
                currentFilePath = parentPath;
                renderFileBrowser();
            } else {
                // Stay at root
                renderFileBrowser(); 
            }
        });
    }

    // Notepad App Events
    openNotepadBtn.addEventListener('click', () => {
        document.getElementById('notepad-window').classList.remove('hidden');
        if(tabsState.length === 0) loadTabs(); // Ensure state loaded
    });

    closeNotepadBtns.forEach(btn => btn.addEventListener('click', () => {
        document.getElementById('notepad-window').classList.add('hidden');
        saveState();
    }));

    // Load saved notepad on start (optional, but good for persistence)
    loadTabs(); 
}

/**
 * WINDOW DRAGGING IMPLEMENTATION
 */
const windows = document.querySelectorAll('.window');
let draggedWindow = null;
let currentX = 0;
let currentY = 0;
let initialX = 0;
let initialY = 0;
let xOffset = 0;
let yOffset = 0;

windows.forEach(win => {
    const header = win.querySelector('.win-header');

    // Make window focusable (bring to front) on click anywhere
    win.addEventListener('mousedown', () => {
        windows.sort((a, b) => a === win ? 1 : -1); // Simple z-index ordering via DOM reordering or style? 
        // CSS `:last-child` in flex container often pushes to top. Since they are siblings inside #desktop (static), we can set Z-Index.
    });

    if(header) {
        header.addEventListener('mousedown', dragWindowStart);
    }
});

function dragWindowStart(e) {
    // Only left click and not window close buttons
    if(e.target.closest('.win-controls')) return; 

    draggedWindow = this.parentElement || document.querySelector(`.window .win-header:contains(${this})`); 
    // Find parent .window element correctly relative to target

    // Re-find properly since `this` is header div, not window div directly in some contexts (actually it's inside)
    const winEl = this.closest('.window');

    initialX = e.clientX - winEl.offsetLeft;
    initialY = e.clientY - winEl.offsetTop;

    draggedWindow = winEl;

    document.addEventListener('mousemove', drag);
    document.addEventListener('mouseup', stopDrag);
}

function drag(e) {
    if (draggedWindow === null) return;

    const currentX = e.clientX;
    const currentY = e.clientY;

    // Calculate new position relative to viewport, constrained slightly? No strict bounds required.

    draggedWindow.style.position = 'absolute';
    draggedWindow.style.left = `${currentX - initialX}px`;
    draggedWindow.style.top = `${currentY - initialY}px`;
}

function stopDrag() {
    if (draggedWindow) {
        // Reset offsets to keep relative movement smooth, or clear? 
        // In this simple implementation we recalculate on every start.
        dragWindowStart(e); // This is tricky because event doesn't carry the offset properly for next move in standard logic usually reset X/Y global vars based on mouse pos.

        // Simpler approach: Store current computed style, update on mousedown relative to that? 
        // Let's just rely on simple math above but ensure we don't accumulate offsets incorrectly over multiple drags without resetting initialX correctly.
    }
    draggedWindow = null;
}

// Override stopDrag logic slightly for correctness:
document.addEventListener('mouseup', function(e) {
    if (draggedWindow === null) return; // Handled in closure above? 
    // Actually the global listener was added inside startDrag. We need to remove it globally once.
});


// Better Drag Logic Implementation using event delegation on document for cleanup:

function initDragging() {
    const headers = document.querySelectorAll('.win-header');

    windows.forEach(win => win.addEventListener('mousedown', () => {
        // Raise Z-Index visually
        windows.forEach(w => w.style.zIndex = 10);
        win.style.zIndex = 20;
    }));

    let isDragging = false;
    let startX, startY, initialLeft, initialTop;
    let targetWin = null;

    headers.forEach(h => {
        h.addEventListener('mousedown', (e) => {
            if(e.target.closest('.win-controls')) return; // Block close buttons

            e.preventDefault(); // Prevent text selection on drag start
            isDragging = true;

            const win = h.parentElement;
            targetWin = win;

            // Get current position relative to desktop offset (if absolute) OR initial layout if static.
            // Since windows are initially centered via CSS transform, we need their computed values.
            const rect = win.getBoundingClientRect();

            startX = e.clientX;
            startY = e.clientY;
            initialLeft = rect.left;
            initialTop = rect.top;

            document.addEventListener('mousemove', onMouseMove);
            document.addEventListener('mouseup', onMouseUp);
        });
    });

    function onMouseMove(e) {
        if (!isDragging || !targetWin) return;

        const dx = e.clientX - startX;
        const dy = e.clientY - startY;

        // Calculate new position. Ensure min-width/height are respected by CSS, so we don't need JS for that.
        targetWin.style.position = 'absolute';
        targetWin.style.left = `${initialLeft + dx}px`;
        targetWin.style.top = `${initialTop + dy}px`;
    }

    function onMouseUp() {
        isDragging = false;
        document.removeEventListener('mousemove', onMouseMove);
        document.removeEventListener('mouseup', onMouseUp);
        targetWin = null;
    }
}

// Run initialization after DOM loads
window.addEventListener('load', () => {
    initDesktop();
    renderFileBrowser(); // Render root items initially for Files window (hidden) so it's ready on open.
    initNotepad();
    initDragging();
});

</script>
